 "content": "from collections import deque

def transform(grid):
    """Recolor the non-background component touching the long color-7 marker."""
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))
    seen = [[False] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] == color:
                        seen[yy][xx] = True
                        q.append((yy, xx))
            comps.append((color, cells))
    # The target object is the differently colored component directly abutting
    # the color-7 line/marker; preserve the marker itself.
    targets = []
    for color, cells in comps:
        if color == 7:
            continue
        touching = any(
            0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 7
            for y, x in cells for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1))
        )
        if touching:
            targets.append(cells)
    out = [row[:] for row in grid]
    for cells in targets:
        for y, x in cells:
            out[y][x] = 7
    return out
"
}

